// worklist: Datenmodell ohne `$` (SPEC → Datenmodell). Die Warteschlange gehört zum Chat (`queue:<sessionId>`), der Verlauf
// zum Projekt (`history:<root>`, höchstens 300 Einträge). Erledigte To-dos stehen nur im Verlauf.
import { DONE_LINES, cleanLang } from './i18n.ts'
import type { Lang } from './i18n.ts'

// skipped: per „Überspringen“ ans Ende gelegt; die Seitenleiste zeigt die Marke, bis es wieder startet (0.4.0)
export type Todo = { id: string; text: string; status: 'open' | 'running'; createdAt: number; startedAt?: number; skipped?: boolean }
export type Queue = { items: Todo[]; paused: boolean }
export type HistoryEntry = { text: string; doneAt: number; durationMs: number; sessionId: string; result: string; how: 'auto' | 'manual' }
export type Cost = { usd: number; calls: number }
export type Settings = { haiku: boolean; doneLine: boolean; settleSeconds: number; maxAutoRun: number; lang: Lang }

const HISTORY_MAX = 300
const TODO_MAX = 2000 // Zeichen pro To-do; der Store hat 4 MiB für alles
export const QUEUE_MAX = 200

export const DEFAULT_SETTINGS: Settings = { haiku: true, doneLine: true, settleSeconds: 3, maxAutoRun: 15, lang: 'en' }

const clampNum = (v: unknown, lo: number, hi: number, d: number) => {
  const n = typeof v === 'number' ? v : Number(v)
  return Number.isFinite(n) ? Math.min(hi, Math.max(lo, Math.round(n))) : d
}

/** userConfig-Werte prüfen (plugin.json → userConfig). */
export function cleanSettings(o: Readonly<Record<string, unknown>>): Settings {
  return {
    haiku: typeof o.haiku === 'boolean' ? o.haiku : DEFAULT_SETTINGS.haiku,
    doneLine: typeof o.doneLine === 'boolean' ? o.doneLine : DEFAULT_SETTINGS.doneLine,
    settleSeconds: clampNum(o.settleSeconds, 1, 30, DEFAULT_SETTINGS.settleSeconds),
    maxAutoRun: clampNum(o.maxAutoRun, 1, 100, DEFAULT_SETTINGS.maxAutoRun),
    lang: cleanLang(o.language),
  }
}

/** Gespeicherte Warteschlange lesen; Unlesbares fällt weg. */
export function cleanQueue(v: unknown): Queue {
  const o = v && typeof v === 'object' ? (v as Record<string, unknown>) : {}
  const raw = Array.isArray(o.items) ? o.items : []
  const items: Todo[] = []
  for (const x of raw) {
    if (!x || typeof x !== 'object') continue
    const t = x as Record<string, unknown>
    if (typeof t.id !== 'string' || typeof t.text !== 'string' || !t.text.trim()) continue
    items.push({
      id: t.id,
      text: t.text,
      status: t.status === 'running' ? 'running' : 'open',
      createdAt: typeof t.createdAt === 'number' ? t.createdAt : 0,
      ...(typeof t.startedAt === 'number' ? { startedAt: t.startedAt } : {}),
      ...(t.skipped === true ? { skipped: true } : {}),
    })
  }
  return { items: items.slice(0, QUEUE_MAX), paused: o.paused === true }
}

export function cleanHistory(v: unknown): HistoryEntry[] {
  if (!Array.isArray(v)) return []
  const out: HistoryEntry[] = []
  for (const x of v) {
    if (!x || typeof x !== 'object') continue
    const h = x as Record<string, unknown>
    if (typeof h.text !== 'string' || typeof h.doneAt !== 'number') continue
    out.push({
      text: h.text,
      doneAt: h.doneAt,
      durationMs: typeof h.durationMs === 'number' ? h.durationMs : 0,
      sessionId: typeof h.sessionId === 'string' ? h.sessionId : '',
      result: typeof h.result === 'string' ? h.result : '',
      how: h.how === 'manual' ? 'manual' : 'auto',
    })
  }
  return out.slice(0, HISTORY_MAX)
}

export function cleanCost(v: unknown): Cost {
  const o = v && typeof v === 'object' ? (v as Record<string, unknown>) : {}
  return { usd: typeof o.usd === 'number' && Number.isFinite(o.usd) ? o.usd : 0, calls: typeof o.calls === 'number' ? o.calls : 0 }
}

/** Neuer Eintrag vorn, die ältesten fallen weg. */
export function pushHistory(list: readonly HistoryEntry[], e: HistoryEntry): HistoryEntry[] {
  return [e, ...list].slice(0, HISTORY_MAX)
}

export function running(q: Queue): Todo | undefined {
  return q.items.find((t) => t.status === 'running')
}

export function openItems(q: Queue): Todo[] {
  return q.items.filter((t) => t.status === 'open')
}

export function nextOpen(q: Queue): Todo | undefined {
  return q.items.find((t) => t.status === 'open')
}

export function add(q: Queue, t: Todo): Queue {
  return { ...q, items: [...q.items, t].slice(0, QUEUE_MAX) }
}

export function remove(q: Queue, id: string): Queue {
  return { ...q, items: q.items.filter((t) => t.id !== id) }
}

/** Status setzen; ein To-do, das wieder läuft, verliert die Marke „übersprungen“. */
export function setStatus(q: Queue, id: string, status: Todo['status'], startedAt?: number): Queue {
  return {
    ...q,
    items: q.items.map((t) => {
      if (t.id !== id) return t
      const { skipped, ...rest } = t
      return { ...rest, status, ...(startedAt !== undefined ? { startedAt } : {}), ...(skipped && status !== 'running' ? { skipped } : {}) }
    }),
  }
}

/** Ein offenes To-do unter den offenen um eins nach oben (-1) oder unten (+1); das laufende bleibt, wo es ist. */
export function move(q: Queue, id: string, by: -1 | 1): Queue {
  const open = q.items.filter((t) => t.status === 'open')
  const i = open.findIndex((t) => t.id === id)
  const j = i + by
  if (i < 0 || j < 0 || j >= open.length) return q
  const swapped = [...open]
  const a = swapped[i]
  const b = swapped[j]
  if (!a || !b) return q
  swapped[i] = b
  swapped[j] = a
  let k = 0
  return { ...q, items: q.items.map((t) => (t.status === 'open' ? (swapped[k++] ?? t) : t)) }
}

/** Überspringen (Knopf, `/todos skip`): offen, ans Ende, mit der Marke `skipped`. */
export function skipToEnd(q: Queue, id: string): Queue {
  const t = q.items.find((x) => x.id === id)
  if (!t) return q
  return { ...q, items: [...q.items.filter((x) => x.id !== id), { id: t.id, text: t.text, status: 'open', createdAt: t.createdAt, skipped: true }] }
}

/** Dasselbe To-do offen ganz nach vorn (Fortsetzen nach STOPP, `/todos retry`); die Marke `skipped` fällt weg. */
export function toFront(q: Queue, id: string): Queue {
  const t = q.items.find((x) => x.id === id)
  if (!t) return q
  return { ...q, items: [{ id: t.id, text: t.text, status: 'open', createdAt: t.createdAt }, ...q.items.filter((x) => x.id !== id)] }
}

/** Laufendes zurück auf offen, an seinem Platz vorn (Stufen 1–2: STOPP). */
export function reopen(q: Queue, id: string): Queue {
  return {
    ...q,
    items: q.items.map((t) => (t.id === id ? { id: t.id, text: t.text, status: 'open', createdAt: t.createdAt, ...(t.skipped ? { skipped: true } : {}) } : t)),
  }
}

/** Erster Satz der Antwort, höchstens 120 Zeichen, ohne Markdown-Zierrat: die Kurz-Ergebniszeile im Verlauf (kostenlos). */
export function firstSentence(answer: string, max = 120): string {
  const plain = answer
    .replace(/(```|~~~)[\s\S]*?(\1|$)/g, ' ')
    // Listen-Marken am Zeilenanfang („1.“, „-“): sonst wäre das Kurz-Ergebnis nur „1.“
    .replace(/^\s*(\d+[.)]|[-*+•])\s+/gm, '')
    .replace(/[`*_#>]+/g, '')
    .replace(/\s+/g, ' ')
    .trim()
  if (!plain) return ''
  const m = plain.match(/^(.+?[.!?])(\s|$)/u)
  const s = (m?.[1] ?? plain).trim()
  if (s.length <= max) return s
  const cut = s.slice(0, max - 1)
  const sp = cut.lastIndexOf(' ')
  return `${sp > max * 0.6 ? cut.slice(0, sp) : cut}…`
}

/**
 * Anzeige ohne die Fertig-Marke: entfernt eine letzte Zeile, die nur „Fertig.“ oder „Done.“ ist (auch fett). Das ist die
 * Marke aus der Schlusszeile (je nach Sprache). Nie mitten in einem Satz; sonst unverändert.
 */
export function hideDoneMarker(text: string): string {
  const m = text.match(/^([\s\S]*?)(?:^|\n)\s*(\*\*|__)?(Fertig|Done)\.(\*\*|__)?\s*$/u)
  if (!m) return text
  return (m[1] ?? '').replace(/\s+$/u, '')
}

/** Alle Fassungen der Schlusszeile, auch frühere: ältere Zeilen im Chat sollen weiter erkannt werden. */
const ALL_DONE_LINES = [
  DONE_LINES.en,
  DONE_LINES.de,
  '(Arbeitsliste: Ist etwas unklar, stell am Ende eine klare Rückfrage. Sonst erledige die Aufgabe vollständig und schließe mit „Fertig.“)',
]

/** Bis 0.2.2 gesendet: `[To-do n/m] <Text>` plus Schlusszeile. Erkennt solche Texte in `turn.start` wieder (Fallback). */
export function isTodoPrompt(text: string): boolean {
  return /^\[To-do \d+\/\d+\] /.test(text)
}

// ---------- Gesendete To-dos (ab 0.3.0 ohne Rahmen) ----------

/**
 * Ein gesendetes To-do, pro Chat gemerkt: Daran erkennen `turn.start` und die Zeile im Chat den Text wieder, denn beim
 * Modell kommt ab 0.3.0 genau Fynns Text an, ohne Präfix. Statt des Texts nur eine Prüfsumme (Store 4 MiB).
 */
// c: eine Fortsetzung („Mach mit diesem To-do weiter …“) statt des To-do-Texts (0.4.0, Knopf „Fortsetzen“)
export type SentRec = { id: string; h: string; n: number; m: number; c?: boolean }

const SENT_MAX = 50

/** Prüfsumme eines gesendeten Texts (FNV-1a, 32 Bit, mit Länge); Leerraum am Rand zählt nicht. */
export function textHash(text: string): string {
  const s = text.trim()
  let h = 0x811c9dc5
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i)
    h = Math.imul(h, 0x01000193) >>> 0
  }
  return `${h.toString(36)}.${s.length.toString(36)}`
}

export function cleanSent(v: unknown): SentRec[] {
  if (!Array.isArray(v)) return []
  const out: SentRec[] = []
  for (const x of v) {
    if (!x || typeof x !== 'object') continue
    const r = x as Record<string, unknown>
    if (typeof r.id !== 'string' || typeof r.h !== 'string' || typeof r.n !== 'number' || typeof r.m !== 'number') continue
    out.push({ id: r.id, h: r.h, n: r.n, m: r.m, ...(r.c === true ? { c: true } : {}) })
  }
  return out.slice(-SENT_MAX)
}

/** Neuer Eintrag hinten, die ältesten fallen weg. */
export function pushSent(list: readonly SentRec[], r: SentRec): SentRec[] {
  return [...list, r].slice(-SENT_MAX)
}

/** Der zuletzt gesendete Eintrag mit genau diesem Text. */
export function findSent(list: readonly SentRec[], text: string): SentRec | undefined {
  const h = textHash(text)
  for (let i = list.length - 1; i >= 0; i--) if (list[i]?.h === h) return list[i]
  return undefined
}

/** Ein To-do, das mit `/name` beginnt, ist ein Befehl: Name ohne Schrägstrich (auch `plugin:skill`), Rest als Argumente. */
export function parseCommand(text: string): { name: string; args: string } | null {
  const m = text.trim().match(/^\/([^\s/]+)(?:\s+([\s\S]*))?$/u)
  if (!m || !m[1]) return null
  return { name: m[1], args: (m[2] ?? '').trim() }
}

/**
 * Der Turn, den ein Skill-Befehl auslöst, beginnt mit `<command-name>/name</command-name>` (CLI 2.1.290, Prototyp). Liefert
 * den Befehl als `/name args`, sonst null.
 */
export function commandOfTurn(text: string): string | null {
  const name = text.match(/<command-name>\/?([^<\s]+)<\/command-name>/u)?.[1]
  if (!name) return null
  const args = (text.match(/<command-args>([\s\S]*?)<\/command-args>/u)?.[1] ?? '').trim()
  return `/${name}${args ? ` ${args}` : ''}`
}

/** Zerlegt einen bis 0.2.2 gesendeten To-do-Text für die Anzeige im Verlauf: Nummer, Gesamtzahl, To-do ohne Schlusszeile. */
export function parseSent(text: string): { n: number; m: number; text: string; withLine: boolean } | null {
  const m = text.trim().match(/^\[To-do (\d+)\/(\d+)\] ([\s\S]*)$/)
  if (!m) return null
  let body = (m[3] ?? '').trim()
  const line = ALL_DONE_LINES.find((l) => body.endsWith(l))
  const withLine = line !== undefined
  if (line) body = body.slice(0, body.length - line.length).trim()
  return body ? { n: Number(m[1]), m: Number(m[2]), text: body, withLine } : null
}

/** Einreihen: Leerzeichen zusammenfassen, Länge begrenzen. */
export function cleanText(text: string): string {
  return text.replace(/[ \t]+/g, ' ').trim().slice(0, TODO_MAX)
}

// ---------- Laufzustand (in $.state, überlebt einen Hot Reload) ----------

// unclear: Claudes letzte Antwort war nach den Regeln nicht eindeutig. fresh (0.4.0): nach Neustart, Resume oder Chatwechsel;
// gesendet wird erst nach einem sauberen Turn-Ende, nach „Start“ oder wenn Fynn einreiht
export type CheckState = 'idle' | 'waiting' | 'checking' | 'ask' | 'blocked' | 'unclear' | 'fresh'
export type PlanItem = { id: string; text: string; status: 'pending' | 'in_progress' | 'completed' }

export type Runtime = {
  sid: string
  busy: boolean
  turnSeq: number
  turn: { startedAt: number; todoId: string | null; text: string; fromFynn: boolean }
  state: CheckState
  stateReason: string
  // kind 'background': Hintergrundarbeit läuft länger als die Wartegrenze (0.4.0); 'cleared': To-do lief beim /clear (0.6.0, bleibt
  // über Fynns Nachricht hinweg stehen); sonst Rückfrage, STOPP oder Halt ohne To-do
  notice: { reason: string; todoId: string | null; kind?: 'background' | 'cleared' } | null
  autoRun: number
  strikes: { id: string; n: number }
  hold: boolean
  plan: PlanItem[]
  sessionDone: number
  expectOwn: string | null
  // Befehls-To-do gesendet (`$.command.run`): Name ohne Schrägstrich, bis sein Turn beginnt oder es ohne Turn abgehakt ist
  expectCmd: string | null
  // Gesendete To-dos dieses Chats (auch in `$.store` `sent:<sessionId>`, damit der Rahmen im Chat nach Resume bleibt)
  sent: SentRec[]
  lastResult: string // Kurz-Ergebnis (erster Satz) der letzten Antwort, nicht die ganze Antwort
  // Warten auf Hintergrundarbeit (0.4.0): Kurzform für die Statuszeile, Beginn der Wartephase, Hinweis schon gezeigt,
  // Aufgaben, auf die nach „Nicht mehr warten“ nicht mehr gewartet wird (IDs; 'cron' für geplante Weckaufträge)
  stateShort: string
  waitSince: number
  waitNoticed: boolean
  ignoreBg: string[]
  // Zeitpunkt des letzten Turn-Endes: Ein /todo kurz danach hat Fynn während dieses Turns getippt (Phase 0, Runde 3)
  turnEndAt: number
}

export function freshRuntime(sid: string): Runtime {
  return {
    sid,
    busy: false,
    turnSeq: 0,
    turn: { startedAt: 0, todoId: null, text: '', fromFynn: false },
    state: 'idle',
    stateReason: '',
    notice: null,
    autoRun: 0,
    strikes: { id: '', n: 0 },
    hold: false,
    plan: [],
    sessionDone: 0,
    expectOwn: null,
    expectCmd: null,
    sent: [],
    lastResult: '',
    stateShort: '',
    waitSince: 0,
    waitNoticed: false,
    ignoreBg: [],
    turnEndAt: 0,
  }
}

files.hooks/view.ts:
// worklist: Anzeige der Seitenleiste ohne `$`. Aus einem View-Modell werden gebaut: Statuszeile mit Fortschritt der Liste,
// JETZT (nur wenn etwas läuft), HINWEIS (nur wenn die Liste anhält), DANACH (Eingabefeld oben, darunter die Liste) und VERLAUF.
// Jeder Bereich wird zwischengespeichert und nur neu gebaut, wenn sich seine Daten, die Breite oder die Sprache ändern: Neu
// gebaute Knöpfe nahmen im Desktop keinen Klick an (mods/quick-replies/SPEC.md, Prototyp 3).
// Kein Svg (mods/orchestrator/SPEC.md:166: interaktives Svg im Pane flackerte im Desktop mit weißem Hintergrund).
import type { Elements, RenderElement, RenderNode } from 'claude-code'
import { dayDate } from './i18n.ts'
import type { Lang, Strings } from './i18n.ts'
import type { PlanItem } from './model.ts'

// Farben aus limit-bars (mods/limit-bars/hooks/view.ts), dort aus der clawd-buddy-Palette
export const ORANGE = '#D77757'
const YELLOW = '#F2C94C'
const EMPTY = '#4A4A4A'
const GREY = '#9A9A9A'

/** Abstand zwischen Knöpfen (SPEC: mindestens 2 Spalten). */
const GAP = 2
const HISTORY_SHORT = 10
const DAY = 86_400_000

type El = Pick<Elements['terminal'], 'Box' | 'Text' | 'Button'> & { Input?: Elements['terminal']['Input'] }

/** Statuszeile ganz oben: Symbol und ein Satz. Farbe nur bei „läuft“ (accent) und „wartet auf dich“ (strong). */
export type Tone = 'accent' | 'strong' | 'dim'
export type StatusLine = { icon: string; text: string; tone: Tone }

/** JETZT: nur, solange Claude arbeitet oder ein To-do läuft bzw. geprüft wird. */
export type NowView = {
  kind: 'todo' | 'chat'
  index: number // 1-basiert, nur bei 'todo'
  total: number
  text: string
  elapsedMs: number
  activity: string
  plan: readonly PlanItem[]
  waiting: string // „wartet auf Hintergrundarbeit: …“, sonst ''
  checking: boolean
}

type QueueItem = { id: string; text: string; skipped: boolean }
type HistoryItem = { text: string; doneAt: number; durationMs: number; result: string; how: 'auto' | 'manual' }

/**
 * Hinweis, wenn die Liste anhält:
 * - question: ein To-do hat eine Rückfrage (Stufen 5–9); Fynns Antwort im Chat setzt es fort
 * - stop: Abbruch, Fehler, unbekannter Befehl (STOPP)
 * - hold: ohne To-do (Schleifenschutz, maxAutoRun); nur „Fortsetzen“
 * - background: Hintergrundarbeit läuft länger als 2 Minuten
 */
export type NoticeKind = 'question' | 'stop' | 'hold' | 'background'
// noResume: nach dem zweiten Halt am selben To-do helfen nur Fynns Antwort, Abhaken oder Überspringen (SPEC 0.4.2)
type Notice = { kind: NoticeKind; reason: string; noResume?: boolean }

/** Knopf in der Kopfzeile von DANACH: Pause, Start (pausiert) oder Jetzt starten (Liste wartet). */
export type Control = 'pause' | 'start' | 'go'

export type View = {
  lang: Lang
  status: StatusLine
  progress: { done: number; total: number } | null
  now: NowView | null
  notice: Notice | null
  queue: readonly QueueItem[]
  control: Control
  draft: string
  history: readonly HistoryItem[] // neueste zuerst
  historyOpen: boolean
  historyAll: boolean
  inputKey: string // Schlüssel des Eingabefelds; wechselt nach jedem Einreihen, damit es leer neu erscheint
  todayStart: number // Mitternacht heute (lokal), für die Gruppen
}

export type Actions = {
  resume: () => void
  markDone: () => void
  skip: () => void
  stopWaiting: () => void
  keepWaiting: () => void
  up: (id: string) => void
  down: (id: string) => void
  remove: (id: string) => void
  add: (text: string) => void
  draft: (text: string) => void
  control: () => void
  toggleHistory: () => void
  toggleAll: () => void
}

/** Laufzeit `m:ss` bzw. `h:mm:ss`. */
export function clock(ms: number): string {
  const s = Math.max(0, Math.floor(ms / 1000))
  const two = (n: number) => String(n).padStart(2, '0')
  const h = Math.floor(s / 3600)
  const m = Math.floor((s % 3600) / 60)
  return h > 0 ? `${h}:${two(m)}:${two(s % 60)}` : `${m}:${two(s % 60)}`
}

/** Dauer im Verlauf (beide Sprachen gleich): `< 1 min`, `4 min`, `1 h 12 min`. */
export function duration(ms: number): string {
  const min = Math.floor(Math.max(0, ms) / 60000)
  if (min < 1) return '< 1 min'
  if (min < 60) return `${min} min`
  return `${Math.floor(min / 60)} h ${min % 60} min`
}

/** Textbalken (kein Svg im Pane). */
function bar(done: number, total: number, width: number): string {
  const w = Math.max(4, width)
  const filled = total <= 0 ? 0 : Math.round((done / total) * w)
  return '▰'.repeat(filled) + '▱'.repeat(w - filled)
}

/** Gruppenname eines Tages im Verlauf: Heute/Today, Gestern/Yesterday, sonst Wochentag und Datum. */
function dayLabel(at: number, todayStart: number, lang: Lang, tx: Strings): string {
  if (at >= todayStart) return tx.today
  if (at >= todayStart - DAY) return tx.yesterday
  return dayDate(lang, at)
}

/** Lange To-dos: höchstens `lines` Zeilen bei `cols` Spalten, an der Wortgrenze gekürzt. */
export function clamp(text: string, cols: number, lines = 3): string {
  const t = text.replace(/\s+/g, ' ').trim()
  const max = Math.max(12, cols) * lines
  if (t.length <= max) return t
  const cut = t.slice(0, max - 1)
  const space = cut.lastIndexOf(' ')
  return `${space > max * 0.6 ? cut.slice(0, space) : cut}…`
}

type Cached = { sig: string; node: RenderNode }

/**
 * Baut die Seitenleiste. `cache` gehört dem Aufrufer und überlebt die Zeichnungen; jeder Bereich bleibt dasselbe Objekt,
 * solange seine Signatur gleich ist. Die Wurzel ist ein neues Objekt, ihre Kinder sind die zwischengespeicherten Bereiche.
 */
export function renderPane(el: El, v: View, tx: Strings, act: Actions, cols: number, surface: string, cache: Map<string, Cached>): RenderElement {
  const width = Math.max(20, cols)
  const part = (name: string, sig: string, build: () => RenderNode): RenderNode => {
    const full = `${surface}|${width}|${v.lang}|${sig}`
    const hit = cache.get(name)
    if (hit && hit.sig === full) return hit.node
    const node = build()
    cache.set(name, { sig: full, node })
    return node
  }
  const children: RenderNode[] = []
  children.push(part('status', JSON.stringify([v.status, v.progress]), () => statusBox(el, v, tx, width)))
  const now = v.now
  if (now) children.push(part('now', JSON.stringify(now), () => nowBox(el, now, tx, width)))
  const notice = v.notice
  if (notice) children.push(part('notice', JSON.stringify(notice), () => noticeBox(el, notice, tx, act)))
  children.push(
    part('queue', JSON.stringify([v.queue, v.control, !!el.Input, v.inputKey]), () => queueBox(el, v, tx, act, width)),
    part('history', JSON.stringify([v.history.length, v.history[0]?.doneAt ?? 0, v.historyOpen, v.historyAll, v.todayStart]), () =>
      historyBox(el, v, tx, act),
    ),
  )
  return el.Box({ flexDirection: 'column', rowGap: 1, children })
}

function statusBox(el: El, v: View, tx: Strings, width: number): RenderNode {
  const { Box, Text } = el
  const s = v.status
  const color = s.tone === 'dim' ? undefined : ORANGE
  const rows: RenderNode[] = [
    Text({ wrap: 'wrap', bold: s.tone === 'strong', color, dimColor: s.tone === 'dim', children: [`${s.icon} ${s.text}`] }),
  ]
  const p = v.progress
  if (p && p.total > 0) {
    rows.push(
      Text({
        wrap: 'truncate-end',
        children: [Text({ color: ORANGE, children: [bar(p.done, p.total, Math.min(24, width - 18))] }), Text({ dimColor: true, children: [` ${tx.progress(p.done, p.total)}`] })],
      }),
    )
  }
  return Box({ flexDirection: 'column', paddingX: 1, children: rows })
}

function nowBox(el: El, now: NowView, tx: Strings, width: number): RenderNode {
  const { Box, Text } = el
  const rows: RenderNode[] = []
  const label = now.kind === 'todo' ? `◆ To-do ${now.index}/${now.total}` : tx.fromChat
  rows.push(
    Box({
      flexDirection: 'row',
      justifyContent: 'space-between',
      children: [Text({ bold: true, color: ORANGE, children: [label] }), Text({ dimColor: true, children: [clock(now.elapsedMs)] })],
    }),
  )
  rows.push(Text({ bold: true, wrap: 'wrap', children: [clamp(now.text, width - 4)] }))
  if (now.activity) rows.push(Text({ color: GREY, wrap: 'truncate-end', children: [`↳ ${now.activity}`] }))
  if (now.waiting) rows.push(Text({ color: YELLOW, wrap: 'truncate-end', children: [now.waiting] }))
  if (now.checking) rows.push(Text({ color: GREY, wrap: 'truncate-end', children: [tx.checkingLine] }))
  if (now.plan.length > 0) {
    const done = now.plan.filter((s) => s.status === 'completed').length
    rows.push(
      Box({
        flexDirection: 'row',
        justifyContent: 'space-between',
        marginTop: 1,
        children: [
          Text({ children: [Text({ color: ORANGE, children: [bar(done, now.plan.length, Math.min(20, width - 16))] }), ` ${done}/${now.plan.length}`] }),
          Text({ dimColor: true, children: [tx.plan] }),
        ],
      }),
    )
    for (const s of now.plan) {
      const mark = s.status === 'completed' ? '✓' : s.status === 'in_progress' ? '▶' : '○'
      rows.push(
        Text({
          wrap: 'truncate-end',
          dimColor: s.status === 'completed',
          strikethrough: s.status === 'completed',
          bold: s.status === 'in_progress',
          children: [`${mark} ${s.text}`],
        }),
      )
    }
  }
  return Box({
    flexDirection: 'column',
    borderStyle: 'round',
    borderColor: ORANGE,
    paddingX: 1,
    children: [Text({ dimColor: true, children: [tx.now] }), ...rows],
  })
}

function noticeBox(el: El, notice: Notice, tx: Strings, act: Actions): RenderNode {
  const { Box, Text, Button } = el
  const text: RenderNode[] = [Text({ bold: true, color: ORANGE, children: [notice.kind === 'background' ? tx.noticeWaitTitle : tx.noticeTitle] }), Text({ wrap: 'wrap', children: [notice.reason] })]
  if (notice.kind === 'question') text.push(Text({ dimColor: true, wrap: 'wrap', children: [tx.answerInChat] }))
  // Die Empfehlung vorn und hervorgehoben; Überspringen klein und mit Abstand, damit es nicht aus Versehen trifft
  const buttons: RenderNode[] =
    notice.kind === 'background'
      ? [
          Button({ key: 'stop-waiting', label: tx.stopWaiting, variant: 'primary', onPress: () => act.stopWaiting() }),
          Button({ key: 'keep-waiting', label: tx.keepWaiting, onPress: () => act.keepWaiting() }),
        ]
      : notice.kind === 'hold'
        ? [Button({ key: 'resume', label: tx.resume, variant: 'primary', onPress: () => act.resume() })]
        : [
            ...(notice.noResume ? [] : [Button({ key: 'resume', label: tx.resume, variant: 'primary', onPress: () => act.resume() })]),
            Button({ key: 'mark-done', label: tx.markDone, ...(notice.noResume ? { variant: 'primary' as const } : {}), onPress: () => act.markDone() }),
            Box({ marginLeft: GAP, children: [Button({ key: 'skip', label: tx.skip, plain: true, onPress: () => act.skip() })] }),
          ]
  return Box({
    flexDirection: 'column',
    borderStyle: 'round',
    borderColor: ORANGE,
    paddingX: 1,
    rowGap: 1,
    children: [
      Box({ flexDirection: 'column', children: text }),
      Box({ flexDirection: 'row', flexWrap: 'wrap', alignItems: 'center', columnGap: GAP, rowGap: 1, children: buttons }),
    ],
  })
}

function queueBox(el: El, v: View, tx: Strings, act: Actions, width: number): RenderNode {
  const { Box, Text, Button, Input } = el
  const rows: RenderNode[] = [
    // Kopfzeile: Titel und Zahl links, Start/Pause rechts
    Box({
      flexDirection: 'row',
      justifyContent: 'space-between',
      alignItems: 'center',
      children: [
        Text({ children: [Text({ bold: true, color: ORANGE, children: [tx.next] }), Text({ dimColor: true, children: [` · ${v.queue.length === 0 ? tx.nothingOpen : tx.nOpen(v.queue.length)}`] })] }),
        Button({
          key: 'pause',
          label: v.control === 'pause' ? tx.pause : v.control === 'start' ? tx.start : tx.go,
          plain: true,
          onPress: () => act.control(),
        }),
      ],
    }),
  ]
  // Eingabefeld oben: die häufigste Aktion. Mobil gibt es keins (types: Elements['mobile']); dort bleibt /todo <Aufgabe>
  if (Input) {
    rows.push(
      Box({
        marginTop: 1,
        marginBottom: v.queue.length > 0 ? 1 : 0,
        children: [
          Input({
            key: v.inputKey,
            label: '+',
            placeholder: tx.placeholder,
            submitLabel: tx.submit,
            // /todo öffnet mit focus: true; der Fokus soll im Eingabefeld stehen (types: InputProps.autoFocus)
            autoFocus: true,
            // Der Entwurf überlebt ein Neuzeichnen (onInput merkt ihn), nach dem Einreihen ist er leer
            value: v.draft,
            onInput: (value: string) => act.draft(value),
            onSubmit: (value: string) => act.add(value),
          }),
        ],
      }),
    )
  }
  v.queue.forEach((q, i) => {
    const first = i === 0
    const last = i === v.queue.length - 1
    rows.push(
      Box({
        flexDirection: 'row',
        alignItems: 'flex-start',
        columnGap: 1,
        children: [
          Text({ color: GREY, children: [`${i + 1}.`] }),
          // Rahmen, Innenabstand, Nummer und die drei Knöpfe abgezogen
          Box({
            flexGrow: 1,
            flexShrink: 1,
            flexDirection: 'column',
            children: [
              Text({ wrap: 'wrap', children: [clamp(q.text, width - 18)] }),
              ...(q.skipped ? [Text({ dimColor: true, children: [tx.skippedMark] })] : []),
            ],
          }),
          Box({
            flexDirection: 'row',
            flexShrink: 0,
            columnGap: GAP,
            children: [
              // Auch am Rand gezeichnet (ohne Wirkung), damit die Spalten untereinander stehen
              Button({ key: `up-${q.id}`, label: '↑', plain: true, onPress: () => (first ? undefined : act.up(q.id)) }),
              Button({ key: `down-${q.id}`, label: '↓', plain: true, onPress: () => (last ? undefined : act.down(q.id)) }),
              Button({ key: `remove-${q.id}`, label: '✕', plain: true, onPress: () => act.remove(q.id) }),
            ],
          }),
        ],
      }),
    )
  })
  return Box({ flexDirection: 'column', borderStyle: 'round', borderColor: EMPTY, paddingX: 1, children: rows })
}

function historyBox(el: El, v: View, tx: Strings, act: Actions): RenderNode {
  const { Box, Text, Button } = el
  const rows: RenderNode[] = [
    Box({
      flexDirection: 'row',
      justifyContent: 'space-between',
      children: [
        Button({ key: 'history', label: `${v.historyOpen ? '▾' : '▸'} ${tx.history}`, plain: true, onPress: () => act.toggleHistory() }),
        Text({ dimColor: true, children: [v.history.length === 0 ? tx.historyEmpty : tx.nDone(v.history.length)] }),
      ],
    }),
  ]
  if (v.historyOpen) {
    const shown = v.historyAll ? v.history : v.history.slice(0, HISTORY_SHORT)
    let day = ''
    for (const h of shown) {
      const d = dayLabel(h.doneAt, v.todayStart, v.lang, tx)
      if (d !== day) {
        day = d
        rows.push(Text({ color: GREY, bold: true, children: [d] }))
      }
      const meta = [duration(h.durationMs), h.how === 'manual' ? tx.byHand : '', h.result].filter(Boolean).join(' · ')
      rows.push(
        Box({
          flexDirection: 'column',
          children: [
            Text({ dimColor: true, strikethrough: true, wrap: 'truncate-end', children: [`✓ ${h.text}`] }),
            Text({ dimColor: true, wrap: 'truncate-end', children: [`  ${meta}`] }),
          ],
        }),
      )
    }
    if (v.history.length > HISTORY_SHORT) {
      rows.push(
        Button({ key: 'history-all', label: v.historyAll ? tx.showLess : tx.showAll(v.history.length), plain: true, onPress: () => act.toggleAll() }),
      )
    }
  }
  return Box({ flexDirection: 'column', paddingX: 1, children: rows })
}

